1	// Acceptance tests for the change request:
2	//   "The money I am owed should only count invoices I have actually sent. Do not count drafts."
3	//
4	// "The money I am owed" is the dashboard's outstanding total (dashboard-outstanding-total) — the
5	// money still to come in. Invoices move through DRAFT -> SENT -> PAID (see invoice-send.spec.ts). A
6	// DRAFT has not gone out yet, so it is NOT money owed; only an invoice I have actually SENT (and not
7	// since been paid) counts as owed. A PAID invoice is already in, so it does not count either (see
8	// dashboard.spec.ts). So: owed = the sum of SENT amounts only — DRAFT and PAID are both excluded.
9	//
10	// Asserts ONLY through the UI (data-testid). Data is arranged via resetAndSeed; the send flow is
11	// driven through the UI. Seed honours clients { id, name, email }, projects { id, clientId, name }
12	// and invoices { id, projectId, amount, status } — status places an invoice at a chosen stage
13	// ('DRAFT' / 'SENT' / 'PAID').
14	//
15	// The owed total is MONEY, so it is asserted in the app's money format — a dollar sign and two
16	// decimals, "$420.00" — per the "show money properly everywhere" change (see money-format.spec.ts).
17	// Amounts are distinct whole numbers under 1000 (so no thousands separator is involved), chosen so
18	// that neither a draft's amount nor any wrong total (a draft wrongly counted) is a substring of the
19	// correct owed total. This SHOULD FAIL before the change: today a sent-but-unpaid invoice is not
20	// counted as owed at all.
21	import { test, expect } from '@playwright/test';
22	import { resetAndSeed } from '../support/seed';
23	
24	// Reach the dashboard through its nav link (the stable contract), re-navigating from the root so the
25	// dashboard figures are read from a fresh load rather than a possibly stale in-page cache.
26	async function openDashboard(page: import('@playwright/test').Page) {
27	  await page.goto('/');
28	  await expect(page.getByTestId('app-root')).toBeVisible();
29	  await page.getByTestId('nav-dashboard').click();
30	  await expect(page.getByTestId('dashboard-page')).toBeVisible();
31	  await expect(page.getByTestId('dashboard')).toBeVisible();
32	  await expect(page.getByTestId('dashboard-loading')).toHaveCount(0);
33	  await expect(page.getByTestId('dashboard-error')).toHaveCount(0);
34	}
35	
36	test.describe('money owed counts only sent invoices, not drafts', () => {
37	  test('a draft is not counted as money owed; only sent invoices are', async ({ page }) => {
38	    await resetAndSeed({
39	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
40	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
41	      invoices: [
42	        // Sent-but-unpaid -> money owed.
43	        { id: 1, projectId: 1, amount: 120, status: 'SENT' },
44	        { id: 2, projectId: 1, amount: 300, status: 'SENT' },
45	        // Still a DRAFT -> not sent yet, so NOT money owed.
46	        { id: 3, projectId: 1, amount: 55, status: 'DRAFT' },
47	        // Already PAID -> already in, so NOT money owed.
48	        { id: 4, projectId: 1, amount: 999, status: 'PAID' },
49	      ],
50	    });
51	
52	    await openDashboard(page);
53	
54	    // Owed is the SENT amounts only: 120 + 300 = 420. The draft (55) and the paid (999) are excluded.
55	    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('$420.00');
56	    // Not the total you would get if the draft were (wrongly) counted in: 420 + 55 = 475.
57	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('475');
58	    // Nor the paid amount.
59	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('999');
60	  });
61	
62	  test('a draft alone is not money owed, but sending it makes it owed', async ({ page }) => {
63	    // One invoice, still a DRAFT. Nothing has been sent, so nothing is owed yet.
64	    await resetAndSeed({
65	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
66	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
67	      invoices: [{ id: 1, projectId: 1, amount: 250, status: 'DRAFT' }],
68	    });
69	
70	    // Before sending: the draft is not money owed — the owed total is zero.
71	    await openDashboard(page);
72	    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('$0.00');
73	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('250');
74	
75	    // Actually send the invoice, through the UI, on its project's detail page.
76	    await page.goto('/projects');
77	    await page.getByTestId('project-open-1').click();
78	    await expect(page.getByTestId('project-detail-page')).toBeVisible();
79	    await page.getByTestId('invoice-send-1').click();
80	    await expect(page.getByTestId('invoice-row-1').getByTestId('invoice-status')).toHaveText(/^sent$/i);
81	
82	    // Now that it has actually been sent, it is money owed: the owed total reflects its amount.
83	    await openDashboard(page);
84	    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('$250.00');
85	  });
86	
87	  test('with every invoice still a draft, nothing is owed', async ({ page }) => {
88	    await resetAndSeed({
89	      clients: [{ id: 1, name: 'Acme Corp', email: 'ops@acme.example' }],
90	      projects: [{ id: 1, clientId: 1, name: 'Website redesign' }],
91	      invoices: [
92	        { id: 1, projectId: 1, amount: 120, status: 'DRAFT' },
93	        { id: 2, projectId: 1, amount: 300, status: 'DRAFT' },
94	      ],
95	    });
96	
97	    await openDashboard(page);
98	
99	    // Drafts are not owed: the total is zero and includes neither draft amount nor their sum (420).
100	    await expect(page.getByTestId('dashboard-outstanding-total')).toContainText('$0.00');
101	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('120');
102	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('300');
103	    await expect(page.getByTestId('dashboard-outstanding-total')).not.toContainText('420');
104	  });
105	});
106

