1	import { existsSync, readFileSync } from 'node:fs';
2	
3	// Read the known audit file — the second test-assertion channel alongside the UI (DESIGN.md §3,
4	// docs/SUT_CONTRACT.md §4). The app appends one record per line; /__test__/reset clears it per
5	// spec. Path comes from AUDIT_FILE (set by bin/start / bin/e2e); falls back to the app's default.
6	const AUDIT_FILE = process.env.AUDIT_FILE ?? '../.run/audit.log';
7	
8	/** All audit records currently in the file, one per element (empty if none). */
9	export function auditLines(): string[] {
10	  return existsSync(AUDIT_FILE)
11	    ? readFileSync(AUDIT_FILE, 'utf8').split('\n').filter((l) => l.length > 0)
